## 1️⃣  IndexedDB helper (tiny wrapper around the `idb` library)

```ts
// npm i idb   (or yarn add idb)
import { openDB, DBSchema, IDBPDatabase } from 'idb';

interface TileDB extends DBSchema {
  /** key = `${z}/${x}/${y}`  (no leading slash) */
  tiles: {
    key: string;
    value: ArrayBuffer; // raw .pbf bytes
  };
}

/** Singleton – open the DB once and reuse it */
let dbPromise: Promise<IDBPDatabase<TileDB>> | null = null;
function getDB(): Promise<IDBPDatabase<TileDB>> {
  if (!dbPromise) {
    dbPromise = openDB<TileDB>('vector-tile-cache', 1, {
      upgrade(db) {
        db.createObjectStore('tiles');
      },
    });
  }
  return dbPromise;
}

/** Read a tile from the cache */
export async function getTileFromCache(
  z: number,
  x: number,
  y: number
): Promise<ArrayBuffer | undefined> {
  const db = await getDB();
  const key = `${z}/${x}/${y}`;
  return db.get('tiles', key);
}

/** Write a tile into the cache (used by the fallback network path) */
export async function putTileInCache(
  z: number,
  x: number,
  y: number,
  data: ArrayBuffer
): Promise<void> {
  const db = await getDB();
  const key = `${z}/${x}/${y}`;
  await db.put('tiles', data, key);
}
```

> **Why `idb`?** It gives you a tiny, promise-based wrapper around IndexedDB with proper TypeScript typings. You can replace it with any other IndexedDB wrapper if you prefer.

---

## 2️⃣  Register the `cache://` protocol

```ts
import maplibregl from 'maplibre-gl';
import { getTileFromCache, putTileInCache } from './tileCache'; // the file from step 1

/**
 * The handler receives the full URL that appears in the style,
 * e.g.  "cache://tiles/12/3456/7890".
 *
 * It must return a Promise that resolves to:
 *   - an ArrayBuffer (raw tile bytes)
 *   - a Response object (like fetch would give you)
 *   - null/undefined to let the default loader try again.
 */
maplibregl.addProtocol('cache', async (params) => {
  // `params` shape: { url: string, request: Request, ... }
  // Strip the scheme and leading slash:
  //   "cache://tiles/12/3456/7890"  →  "tiles/12/3456/7890"
  const path = params.url.replace(/^cache:\/\//, '');

  // Expect the pattern "tiles/{z}/{x}/{y}"
  const match = path.match(/^tiles\/(\d+)\/(\d+)\/(\d+)$/);
  if (!match) {
    console.warn('cache protocol: unexpected URL', params.url);
    return null; // let the default loader handle it (will 404)
  }

  const [, zStr, xStr, yStr] = match;
  const z = Number(zStr);
  const x = Number(xStr);
  const y = Number(yStr);

  // 1️⃣ Try the cache first
  const cached = await getTileFromCache(z, x, y);
  if (cached) {
    // Return the raw bytes – MapLibre will treat it as a tile response.
    return cached;
  }

  // 2️⃣ Not in cache → fetch from the real source, store, then return.
  //   You can hard-code the remote URL pattern or keep it configurable.
  const remoteUrl = `https://my.tileserver.com/tiles/${z}/${x}/${y}.pbf`;

  try {
    const response = await fetch(remoteUrl);
    if (!response.ok) {
      console.error(`Failed to fetch ${remoteUrl}: ${response.status}`);
      return null; // fallback – map will show a missing-tile placeholder
    }
    const arrayBuffer = await response.arrayBuffer();

    // Store it for next time (fire-and-forget)
    putTileInCache(z, x, y, arrayBuffer).catch((e) =>
      console.error('Failed to write tile to cache', e)
    );

    // Return the bytes (or the whole Response – both work)
    return arrayBuffer;
  } catch (err) {
    console.error('Network error while fetching tile', err);
    return null;
  }
});
```

**Important notes**

| What | Why |
|------|-----|
| **Register *before* creating the map** | `addProtocol` is global; the map reads the style synchronously on construction. |
| **Return `ArrayBuffer` (or `Response`)** | MapLibre GL JS expects the raw tile bytes. Returning a `Response` gives you more control (e.g., custom headers). |
| **Return `null` on error** | The renderer will treat the tile as missing and draw the “no-data” placeholder, instead of crashing. |
| **Do not block the UI** | All I/O is async (`await`). The handler runs on the main thread, but the heavy work (IndexedDB) is already promise-based and non-blocking. |

