      "minzoom": 0,
      "maxzoom": 14
    }
  },
  "layers": [
    {
      "id": "my-fill",
      "type": "fill",
      "source": "my-vector",
      "source-layer": "my_layer_name",
      "paint": {
        "fill-color": "#88c0d0",
        "fill-opacity": 0.6
