## 4️⃣  Full minimal example (HTML + TS)

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>MapLibre GL JS – IndexedDB cache (cache://)</title>
  <link href="https://unpkg.com/maplibre-gl@4.2.0/dist/maplibre-gl.css" rel="stylesheet" />
  <style>
    #map { position: absolute; top:0; bottom:0; left:0; right:0; }
  </style>
</head>
<body>
  <div id="map"></div>

  <script type="module">
    import maplibregl from 'https://unpkg.com/maplibre-gl@4.2.0/dist/maplibre-gl.esm.js';
    import { openDB } from 'https://cdn.jsdelivr.net/npm/idb@8/+esm';

    // ---------- 1️⃣ IndexedDB helpers ----------
    const dbPromise = openDB('vector-tile-cache', 1, {
      upgrade(db) {
        db.createObjectStore('tiles');
      },
    });

    async function getTile(z, x, y) {
      const db = await dbPromise;
      return db.get('tiles', `${z}/${x}/${y}`);
    }

    async function putTile(z, x, y, data) {
      const db = await dbPromise;
      await db.put('tiles', data, `${z}/${x}/${y}`);
    }

    // ---------- 2️⃣ Register cache:// ----------
    maplibregl.addProtocol('cache', async ({ url }) => {
      const m = url.match(/^cache:\/\/tiles\/(\d+)\/(\d+)\/(\d+)$/);
      if (!m) return null;
      const [, z, x, y] = m.map(Number);

      // Try cache
      const cached = await getTile(z, x, y);
      if (cached) return cached;

      // Not cached → fetch from remote, store, return
      const remote = `https://demo.maptiler.com/tiles/v3/tiles/${z}/${x}/${y}.pbf`;
      const resp = await fetch(remote);
      if (!resp.ok) return null;
      const buf = await resp.arrayBuffer();
      putTile(z, x, y, buf).catch(console.error);
      return buf;
    });

    // ---------- 3️⃣ Create the map ----------
    const map = new maplibregl.Map({
      container: 'map',
      style: {
        version: 8,
        sources: {
          demo: {
            type: 'vector',
            tiles: ['cache://tiles/{z}/{x}/{y}'],
            minzoom: 0,
            maxzoom: 14,
          },
        },
        layers: [
          {
            id: 'water',
            type: 'fill',
            source: 'demo',
            'source-layer': 'water',
            paint: { 'fill-color': '#a0c8f0' },
          },
        ],
      },
      center: [0, 0],
      zoom: 2,
    });
  </script>
</body>
</html>
```

*Open the page, pan/zoom, and watch the network tab – after the first request each tile is served from IndexedDB (no network traffic).*

