## 1️⃣  IndexedDB helper – a tiny wrapper around the native API

```ts
// idb.ts – a very small, typed wrapper (you can also use the popular `idb` library)
export interface TileCacheDB extends IDBDatabase {
  /** Returns the stored ArrayBuffer for a tile key, or undefined if not present */
  getTile(key: string): Promise<ArrayBuffer | undefined>;

  /** Stores an ArrayBuffer for a tile key */
  putTile(key: string, data: ArrayBuffer): Promise<void>;
}

/** Open (or create) the IndexedDB database */
export async function openTileCacheDB(): Promise<TileCacheDB> {
  return new Promise<TileCacheDB>((resolve, reject) => {
    const request = indexedDB.open('tile-cache', 1);
    request.onupgradeneeded = () => {
      const db = request.result;
      // One object store, key = `${z}/${x}/${y}`
      db.createObjectStore('tiles');
    };
    request.onsuccess = () => resolve(request.result as TileCacheDB);
    request.onerror = () => reject(request.error);
  });
}

/** Add the two convenience methods to the DB instance */
function augment(db: IDBDatabase): TileCacheDB {
  const cache = db as TileCacheDB;

  cache.getTile = async (key: string) => {
    return new Promise<ArrayBuffer | undefined>((resolve, reject) => {
      const tx = cache.transaction('tiles', 'readonly');
      const store = tx.objectStore('tiles');
      const getReq = store.get(key);
      getReq.onsuccess = () => resolve(getReq.result as ArrayBuffer | undefined);
      getReq.onerror = () => reject(getReq.error);
    });
  };

  cache.putTile = async (key: string, data: ArrayBuffer) => {
    return new Promise<void>((resolve, reject) => {
      const tx = cache.transaction('tiles', 'readwrite');
      const store = tx.objectStore('tiles');
      const putReq = store.put(data, key);
      putReq.onsuccess = () => resolve();
      putReq.onerror = () => reject(putReq.error);
    });
  };

  return cache;
}

/** Export a singleton that you can import elsewhere */
export const tileCache = (async () => {
  const db = await openTileCacheDB();
  return augment(db);
})();
```

*You can place the file in `src/idb.ts` (or any location you like) and import `tileCache` wherever you need it.*

