## 2️⃣  Register the `cache://` protocol

```ts
// protocol.ts
import maplibregl, { RequestParameters, ResponseCallback } from 'maplibre-gl';
import { tileCache } from './idb';

// ---------------------------------------------------------------------------
// 1️⃣  The protocol handler
// ---------------------------------------------------------------------------
async function cacheProtocolHandler(
  params: RequestParameters,
  callback: ResponseCallback
): Promise<void> {
  // `params.url` looks like:  cache://tiles/12/3456/7890
  // Strip the scheme and keep the path that we will use as the DB key.
  const url = new URL(params.url);
  const key = url.pathname.replace(/^\/+/, ''); // "tiles/12/3456/7890"

  // 1️⃣ Try to read from IndexedDB
  const db = await tileCache; // resolves the singleton from idb.ts
  const cached = await db.getTile(key);

  if (cached) {
    // Cache hit – return the raw bytes.
    callback(null, cached, null, null);
    return;
  }

  // 2️⃣ Cache miss – fetch from the network, store, then return.
  // You can decide where the real tiles live.  In this example we assume
  // they are hosted at `https://my.tileserver.com/tiles/{z}/{x}/{y}.pbf`.
  const networkUrl = `https://my.tileserver.com/${key}.pbf`;

  try {
    const response = await fetch(networkUrl);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);

    const arrayBuffer = await response.arrayBuffer();

    // Store for next time (fire-and-forget, we don’t need to wait)
    db.putTile(key, arrayBuffer).catch(console.error);

    // Return the freshly-fetched bytes
    callback(null, arrayBuffer, null, null);
  } catch (err) {
    // If the network request fails we forward the error to the map.
    // The map will treat the tile as missing (transparent background).
    callback(err as Error, null, null, null);
  }
}

// ---------------------------------------------------------------------------
// 2️⃣  Register the protocol (promise-based API, v4+)
// ---------------------------------------------------------------------------
maplibregl.addProtocol('cache', cacheProtocolHandler);
```

**What the handler receives**

| Argument | Meaning |
|----------|---------|
| `params` | `{ url: string, kind: 'source' | 'glyphs' | 'sprite' | … }` – the full request URL and the type of resource. |
| `callback` | `(error, data?, cacheControl?, expires?)` – you must call it exactly once. `data` is an `ArrayBuffer` (or `null` on error). |

> **Important:** The handler **must** call `callback` – returning a Promise alone is not enough for the current MapLibre GL JS implementation.

---

## 3️⃣  Use the protocol in a style

You can reference the custom scheme directly in the style JSON (or in a style URL that you load later).  
Below is a minimal style that loads a vector source from `cache://` and draws a simple fill layer.

```ts
// style.ts – a tiny inline style (you could also load a remote JSON file)
export const styleWithCache: maplibregl.StyleSpecification = {
  version: 8,
  sources: {
    // The source URL uses the custom scheme.
    // The `{z}/{x}/{y}` placeholders are automatically replaced by the map.
    myTiles: {
      type: 'vector',
      // The path after the scheme is the key we store in IndexedDB.
      // Example key for z=12, x=3456, y=7890 → "tiles/12/3456/7890"
      url: 'cache://tiles/{z}/{x}/{y}'
    }
  },
  layers: [
    {
      id: 'my-fill',
      type: 'fill',
      source: 'myTiles',
      'source-layer': 'my_layer_name', // <-- change to the actual layer name in your MVT
      paint: {
        'fill-color': '#3bb2d0',
        'fill-opacity': 0.6
      }
    }
  ]
};
```

> **Tip:** If you already have a style that points to a regular HTTP URL, you can simply replace `https://…` with `cache://` (keeping the same path pattern). The protocol handler will translate it to the real network URL when a cache miss occurs.

---

## 4️⃣  Put it all together – the main entry point

```ts
// index.ts (or main.ts)
import maplibregl from 'maplibre-gl';
import './protocol'; // registers the cache:// handler (side-effect import)
import { styleWithCache } from './style';

// ---------------------------------------------------------------
// 1️⃣  Create the map
// ---------------------------------------------------------------
const map = new maplibregl.Map({
  container: 'map',               // <div id="map"></div> in your HTML
  style: styleWithCache,          // the style that uses cache://
  center: [0, 0],                 // lon, lat
  zoom: 2,
  hash: true
});

// ---------------------------------------------------------------
// 2️⃣  Optional: show a loading spinner while tiles are being fetched
// ---------------------------------------------------------------
map.on('data', (e) => {
  if (e.sourceId === 'myTiles' && e.isSourceLoaded) {
    console.log('All cached tiles for the current view are loaded');
  }
});

// ---------------------------------------------------------------
// 3️⃣  (Optional) Pre-populate the cache on first run
// ---------------------------------------------------------------
async function warmCache() {
  const db = await tileCache;
  // Example: pre-fetch tiles for zoom 0-2 (world overview)
  for (let z = 0; z <= 2; z++) {
    const max = Math.pow(2, z);
    for (let x = 0; x < max; x++) {
      for (let y = 0; y < max; y++) {
        const key = `tiles/${z}/${x}/${y}`;
        if (await db.getTile(key)) continue; // already cached

        const networkUrl = `https://my.tileserver.com/${key}.pbf`;
        try {
          const resp = await fetch(networkUrl);
          if (!resp.ok) continue;
          const buf = await resp.arrayBuffer();
          await db.putTile(key, buf);
          console.log(`Prefetched ${key}`);
        } catch (e) {
          console.warn(`Failed to prefetch ${key}`, e);
        }
      }
    }
  }
}

// Call once (or on a button press) if you want to seed the cache.
warmCache().catch(console.error);
```

**HTML skeleton**

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>MapLibre GL JS – cache:// protocol demo</title>
  <link href="https://unpkg.com/maplibre-gl@4.4.0/dist/maplibre-gl.css" rel="stylesheet"/>
  <style>
    #map { position: absolute; top:0; bottom:0; left:0; right:0; }
  </style>
</head>
<body>
  <div id="map"></div>

  <!-- Bundle your TypeScript (e.g., via Vite, Webpack, or esbuild) -->
  <script type="module" src="/dist/index.js"></script>
</body>
</html>
```

